begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
insert into auth.users(id,email) values('e0000000-0000-4000-8000-000000000001','voice-one@example.test'),('e0000000-0000-4000-8000-000000000002','voice-two@example.test');
insert into learning_sessions(id,user_id,status) values('e1000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001','active');
insert into activities(id,user_id,session_id,sequence_no,activity_type,learning_purpose,difficulty_level,english_exposure_level,correction_strategy,status,metadata) values('e2000000-0000-4000-8000-000000000001','e0000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000001',0,'normal_learning','communication',1,1,'hint_first','active','{"task":{"spoken":true},"support":0}');
select is(record_browser_transcript('e0000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','Water please'),'e3000000-0000-4000-8000-000000000001'::uuid,'confirmed transcript has stable receipt');
select is(record_browser_transcript('e0000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','Water please'),'e3000000-0000-4000-8000-000000000001'::uuid,'retry is idempotent');
select is((select count(*)::int from voice_interactions where activity_id='e2000000-0000-4000-8000-000000000001'),1,'retry does not inflate attempts');
select throws_ok($$select record_browser_transcript('e0000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001','e3000000-0000-4000-8000-000000000001','changed')$$,'P0001','Transcript attempt changed','retry cannot replace confirmed text');
select is((select provider from voice_interactions where id='e3000000-0000-4000-8000-000000000001'),'browser_native','records actual provider');
select is((select recognition_status from voice_interactions where id='e3000000-0000-4000-8000-000000000001'),'client_confirmed_unverified','retains uncertainty');
select is((select audio_object_path from voice_interactions where id='e3000000-0000-4000-8000-000000000001'),null,'no microphone audio stored');
select is((select count(*)::int from learner_ability_estimates where user_id='e0000000-0000-4000-8000-000000000001'),0,'transcript receipt never writes ability');
select throws_ok($$select record_browser_transcript('e0000000-0000-4000-8000-000000000002','e2000000-0000-4000-8000-000000000001',gen_random_uuid(),'Water')$$,'P0001','Invalid activity','cross-user transcript denied');
select throws_ok($$select record_browser_transcript('e0000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',gen_random_uuid(),' ')$$,'P0001','Invalid transcript','empty transcript denied');
update activities set metadata=metadata||jsonb_build_object('lease_until',now()+interval '1 minute') where id='e2000000-0000-4000-8000-000000000001';
select throws_ok($$select record_browser_transcript('e0000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',gen_random_uuid(),'Water')$$,'P0001','Response processing','recognition cannot race a response lease');
select ok(not has_function_privilege('authenticated','public.record_browser_transcript(uuid,uuid,uuid,text)','EXECUTE'),'ordinary clients cannot forge receipts');
update learning_sessions set status='completed' where id='e1000000-0000-4000-8000-000000000001';
select throws_ok($$select record_browser_transcript('e0000000-0000-4000-8000-000000000001','e2000000-0000-4000-8000-000000000001',gen_random_uuid(),'Water')$$,'P0001','Inactive session','closed sessions reject new transcripts');
select * from finish();
rollback;
